{
  "contract": "Yeeter",
  "closure": {
    "site_function": "yeetyeet",
    "site_call": ".call",
    "functions": [
      "<fallback>",
      "yeetyeet",
      "goalReached"
    ],
    "justification": "All public/external functions that touch 'balance' and 'deposits' are included."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>",
      "goalReached"
    ],
    "nesting_bound": {
      "yeetyeet": 1
    }
  },
  "phases": {
    "function": "yeetyeet",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount in transfer during callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_deposits == balance + inFlight",
    "stable_formula": "_sum_deposits == balance",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_deposits == balance",
    "rule": "mapping-conservation"
  }
}
